// ============================================================================
// PASO 5: Clasificación de Carpeta Espejo + Fragmentación Inteligente
// ============================================================================
const driveFile = $('2. Buscar PDF en Google Drive (01_PDF_Original)').first().json;
const rawText = ($input.first().json.text || '').replace(/\r\n/g, '\n');

// Determinar la subcarpeta espejo según el nombre o ruta
const upperName = (driveFile.name || '').toUpperCase();
let folderCategory = '02_leyes';
if (upperName.includes('REGISTRO') || upperName.startsWith('RO_') || upperName.startsWith('RS1_') || upperName.startsWith('RS_') || upperName.includes('HISTORICO')) folderCategory = '00_registros_oficiales';
else if (upperName.includes('CODIGO') || upperName.startsWith('CT')) folderCategory = '01_codigos';
else if (upperName.includes('RLRTI') || upperName.includes('REGLAMENTO')) folderCategory = '03_reglamentos';
else if (upperName.includes('LRET') || upperName.includes('REFORMA')) folderCategory = '04_leyes_reformas';
else if (upperName.includes('NAC-') || upperName.includes('RESOLUCION') || upperName.includes('DGER')) folderCategory = '05_resoluciones_sri';
else if (upperName.includes('CIRCULAR') || upperName.includes('DGECC')) folderCategory = '06_circulares_sri';
else if (upperName.includes('FORMULARIO') || upperName.includes('ANEXO')) folderCategory = '07_formularios_anexos';

const MAX_CHUNK_SIZE = 14000;
const boundaryRegex = /\n(?=\s*(?:T[ÍI]TULO\s+[IVXLCDM0-9]+|CAP[ÍI]TULO\s+[IVXLCDM0-9]+|DISPOSICIONES\s+(?:GENERALES|TRANSITORIAS|REFORMATORIAS|DEROGATORIAS|FINALES)|Art(?:[íi]culo|\.)\s*\d+\s*(?:[-–—.:]|\b)))/gi;

const splitPoints = [0];
let match;
while ((match = boundaryRegex.exec(rawText)) !== null) {
  if (match.index > 0) splitPoints.push(match.index);
}
splitPoints.push(rawText.length);

const chunks = [];
let chunkStart = 0;
let currentTitle = 'SIN TÍTULO';
let currentChapter = 'SIN CAPÍTULO';

for (let i = 1; i < splitPoints.length; i++) {
  const point = splitPoints[i];
  if (point - chunkStart >= MAX_CHUNK_SIZE || i === splitPoints.length - 1) {
    const endPos = i === splitPoints.length - 1 ? rawText.length : point;
    const sliceText = rawText.slice(chunkStart, endPos).trim();

    if (sliceText.length > 0) {
      chunks.push({
        google_drive_file_id: driveFile.id,
        file_name: driveFile.name,
        folder_category: folderCategory,
        storage_path: `${folderCategory}/${driveFile.name}`,
        google_drive_path: `01_PDF_Original/${folderCategory}/${driveFile.name}`,
        sha256: driveFile.sha256Checksum || null,
        file_size: driveFile.size ? Number(driveFile.size) : null,
        source_url: driveFile.webViewLink || null,
        chunk_index: chunks.length,
        char_start: chunkStart,
        char_end: endPos,
        context_title_before: currentTitle,
        context_chapter_before: currentChapter,
        chunk_text: sliceText
      });
    }

    const titles = [...sliceText.matchAll(/(?:^|\n)\s*(T[ÍI]TULO\s+[^\n]+)/gi)];
    if (titles.length > 0) currentTitle = titles[titles.length - 1][1].trim();

    const chapters = [...sliceText.matchAll(/(?:^|\n)\s*(CAP[ÍI]TULO\s+[^\n]+)/gi)];
    if (chapters.length > 0) currentChapter = chapters[chapters.length - 1][1].trim();

    chunkStart = endPos;
  }
}

return chunks.map(c => ({ json: c }));

