// ============================================================================
// PASO 7: Consolidador y Publicación Instantánea + Reformas Cronológicas
// ============================================================================
const driveFile = $('2. Buscar PDF en Google Drive (01_PDF_Original)').first().json;
const firstChunk = $('5. Fragmentador Jurídico con Carpeta Espejo').first().json;
const allItems = $input.all();
const seenArticles = new Map();
const consolidated = [];

for (const item of allItems) {
  const out = item.json.output || item.json;
  const list = out.articulos_detectados || [];
  for (const art of list) {
    const key = `${(art.tipo_estructura || 'article').toLowerCase()}_${String(art.numero).trim().toUpperCase()}`;
    if (!seenArticles.has(key)) {
      seenArticles.set(key, true);
      consolidated.push({
        ordinal: consolidated.length + 1,
        structure_type: art.tipo_estructura || 'article',
        identifier: String(art.numero).trim(),
        title: art.encabezado || `Art. ${art.numero}`,
        parent_title: art.titulo_padre || null,
        parent_chapter: art.capitulo_padre || null,
        content: art.texto_completo_markdown,
        valid_from: art.fecha_inicio_vigencia || null,
        valid_until: art.fecha_fin_vigencia || null,
        official_registry: art.registro_oficial_cita || null,
        reforms_target_norm_code: art.reforma_norma_objetivo || null,
        reforms_target_article_identifier: art.reforma_articulo_objetivo || null,
        reformed_target_content: art.texto_consolidado_post_reforma || null,
        vertical_concepts: art.conceptos_verticales || [],
        has_normative_table: Boolean(art.tiene_tabla_normativa),
        normative_tables: art.tablas_normativas || [],
        detected_relations: art.relaciones_detectadas || [],
        observations: art.observaciones || '',
        review_status: 'approved'
      });
    }
  }
}

let normCode = 'LRTI';
const upperName = (driveFile.name || '').toUpperCase();
if (upperName.includes('RLRTI') || upperName.includes('REGLAMENTO')) normCode = 'RLRTI';
else if (upperName.includes('CODIGO') || upperName.startsWith('CT')) normCode = 'CT';
else if (upperName.includes('NAC-') || upperName.includes('DGER')) normCode = driveFile.name.replace(/\.pdf$/i, '');
else if (upperName.includes('LRET')) normCode = 'LRET';

return [{
  json: {
    p_document_id: null,
    p_norm_code: normCode,
    p_version_title: `Publicado desde Registro Oficial (${driveFile.name})`,
    p_published_on: consolidated[0]?.valid_from || '2004-11-17',
    p_model: 'gemini-2.5-flash',
    p_articles: consolidated,
    p_google_drive_file_id: driveFile.id,
    p_google_drive_path: firstChunk.google_drive_path,
    p_storage_bucket: 'legal-documents',
    p_storage_path: firstChunk.storage_path,
    p_folder_category: firstChunk.folder_category,
    p_file_name: driveFile.name,
    p_sha256: driveFile.sha256Checksum || null,
    p_file_size: driveFile.size ? Number(driveFile.size) : null,
    p_source_url: driveFile.webViewLink || null
  }
}];
